def is_adult(age):
    """Return True if age is 18 or more."""
    return age >= 18

def fare(age):
    if is_adult(age):
        return 100
    return 50

def is_prime(n):
    if n < 2:
        return False
    i = 2
    while i * i <= n:
        if n % i == 0:
            return False
        i += 1
    return True

def count_set_bits(n):
    c = 0
    while n:
        c += n & 1
        n >>= 1
    return c

def two_sum(nums, target):
    seen = {}
    for i, x in enumerate(nums):
        if target - x in seen:
            return [seen[target - x], i]
        seen[x] = i

def compress(s):
    out, i = [], 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append(s[i] + (str(j - i) if j - i > 1 else ''))
        i = j
    return ''.join(out)

class Student:
    def __init__(self, name, marks):
        self.name, self.marks = name, marks

    def average(self):
        return sum(self.marks) / len(self.marks)

s = Student("Harika", [90, 85, 88])
print(s.average())

